                    return getAmount(total).add(getAmount(obj.linkedPaymentAmount));
                }
                return total;
            }, 0);
        } else {
            totalLinkedPaymentAmount = outstandingTableLines.reduce((total, obj) => {
                return getAmount(total).add(getAmount(obj.linkedPaymentAmount));
            }, 0);
        }

